const { test } = require('node:test');
const assert = require('node:assert/strict');
const { spawnSync } = require('node:child_process');
const path = require('node:path');

const cli = path.join(__dirname, '..', 'bin', 'greet.js');

function checkGreeting(args, expected) {
  const result = spawnSync(process.execPath, [cli, ...args], { encoding: 'utf8' });

  assert.equal(result.status, 0);
  assert.equal(result.stdout, expected);
  assert.equal(result.stderr, '');
}

test('greets a named person', () => {
  checkGreeting(['Mike'], 'Hello, Mike!\n');
});

test('greets the world when no name is given', () => {
  checkGreeting([], 'Hello, world!\n');
});

test('prints the version', () => {
  checkGreeting(['--version'], '0.1.0\n');
});

test('version takes precedence after a name', () => {
  checkGreeting(['Mike', '--version'], '0.1.0\n');
});

test('version takes precedence before a name', () => {
  checkGreeting(['--version', 'Mike'], '0.1.0\n');
});
